-- Table: scenarios
DROP TABLE IF EXISTS scenarios CASCADE;
CREATE TABLE scenarios (
id INTEGER NOT NULL DEFAULT nextval('scenarios_id_seq'::regclass),
departement VARCHAR NOT NULL,
metier VARCHAR NULL,
nom_cas_usage VARCHAR NOT NULL,
prompt TEXT NOT NULL,
sortie_attendue TEXT NULL,
critere_succes TEXT NULL,
type_categorie VARCHAR NULL,
  PRIMARY KEY (id)
);

INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (1, 'RH & Communication', 'Recruteur / Talent Acquisition Specialist', 'Rédaction de fiche de poste', 'Rédige une fiche de poste pour un Développeur Backend Python, 3 ans d''expérience minimum, poste basé à Tunis, CDI, pour une entreprise de télécommunications.', 'Fiche structurée avec titre, missions (5-6 points), profil recherché, compétences techniques, avantages.', 'Structure complète, ton professionnel, pas d''information inventée non cohérente, 200-400 mots.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (2, 'RH & Communication', 'Recruteur / Talent Acquisition Specialist', 'Tri et présélection des CV', 'Voici un CV : [texte du CV]. Résume les compétences clés et l''expérience du candidat, et indique s''il correspond à un poste de Développeur Python 3 ans d''expérience.', 'Résumé structuré : compétences, expérience, correspondance au poste (oui/non/partiel avec justification).', 'Extraction fidèle au CV fourni, pas d''invention d''informations absentes du texte.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (3, 'RH & Communication', 'Recruteur / Talent Acquisition Specialist', 'Préparation grille d''évaluation entretien', 'Génère 8 questions d''entretien (4 techniques, 4 comportementales) pour un poste de Développeur Python 3 ans d''expérience, en te basant sur un écart identifié : le candidat n''a pas d''expérience en tests unitaires.', 'Liste de 8 questions classées par catégorie, avec une question ciblant spécifiquement l''écart mentionné.', 'Questions pertinentes et non génériques, au moins une question liée à l''écart précisé.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (4, 'RH & Communication', 'Chargé de Communication Interne', 'Rédaction de communiqué interne', 'Rédige un communiqué interne annonçant un changement d''horaires de travail (nouveaux horaires : 8h30-17h30), sur un ton empathique et rassurant, à destination de tous les employés.', 'Communiqué structuré avec objet, contexte du changement, nouvelles modalités, contact pour questions.', 'Ton empathique respecté, informations claires, longueur adaptée (150-250 mots).', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (5, 'RH & Communication', 'Chargé de Communication Interne', 'Chatbot support RH (RAG)', 'Un employé demande : ''Combien de jours de congé annuel ai-je droit, et comment faire ma demande ?'' Réponds en te basant uniquement sur le règlement interne fourni en contexte.', 'Réponse précise citant le nombre de jours et la procédure, basée sur le document source fourni.', 'Réponse fidèle au document source (pas d''invention), ton clair et direct.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (6, 'Marketing & Digital', 'Responsable de Campagnes Digitales', 'Génération de copies publicitaires', 'Génère 5 variantes de message SMS (max 160 caractères chacun) pour une promotion 4G+ à l''occasion du Ramadan, ciblant un public jeune urbain.', '5 messages courts, distincts, respectant la limite de caractères, ton dynamique adapté à la cible.', 'Respect strict de la limite de 160 caractères, messages non redondants entre eux.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (7, 'Marketing & Digital', 'Concepteur-Rédacteur / Brand Content Manager', 'Rédaction d''article de blog / FAQ', 'Rédige un article de blog de 400 mots expliquant les avantages de la 5G pour les entreprises, optimisé SEO autour du mot-clé ''connectivité 5G entreprise''.', 'Article structuré avec titre accrocheur, introduction, 3 sections, conclusion, mot-clé intégré naturellement.', 'Longueur respectée (~400 mots), mot-clé présent au moins 3 fois de façon naturelle, pas de bourrage de mots-clés.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (8, 'IT & Architecture', 'Développeur Logiciel / Ingénieur d''Études', 'Génération de code', 'Écris une fonction Python qui valide qu''une adresse email est correctement formatée, avec gestion des cas limites, accompagnée d''un test unitaire.', 'Code Python fonctionnel avec la fonction de validation et au moins 3 tests unitaires (cas valide, invalide, limite).', 'Code exécutable sans erreur, gère les cas limites (email vide, sans @, sans domaine).', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (9, 'IT & Architecture', 'Développeur Logiciel / Ingénieur d''Études', 'Modernisation de code legacy', 'Voici un script COBOL simple qui calcule une facture : [extrait de code]. Traduis-le en Python moderne en conservant la même logique métier.', 'Code Python équivalent fonctionnellement, avec commentaires expliquant la correspondance avec l''original.', 'Logique métier préservée, code Python idiomatique, pas de perte de fonctionnalité.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (10, 'IT & Architecture', 'Développeur Logiciel / Ingénieur d''Études', 'Génération de documentation technique', 'Voici une fonction Python : [code de la fonction]. Génère une documentation technique claire (docstring + explication) pour cette fonction, à destination d''autres développeurs.', 'Docstring complet (paramètres, retour, exceptions) + paragraphe explicatif du fonctionnement.', 'Documentation fidèle au code fourni, format docstring standard (ex: Google style ou NumPy style).', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (11, 'Réseau / Support Technique (NOC)', 'Technicien Support Clientèle Entreprises (B2B)', 'Résolution d''incidents complexes', 'Un client B2B signale une panne de liaison louée depuis 2h. Voici l''historique de 3 incidents similaires : [texte des tickets]. Suggère les 3 étapes de résolution prioritaires.', 'Liste de 3 étapes classées par priorité, justifiées par les cas similaires fournis.', 'Étapes cohérentes avec l''historique fourni, priorisation logique et justifiée.', 'Direction');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (12, 'Productivité Personnelle', 'Chef de Projet / Manager', 'Rédaction de compte-rendu de réunion', 'Voici la transcription brute d''une réunion de suivi de projet : [texte transcript]. Rédige un compte-rendu structuré avec décisions prises et actions assignées.', 'Compte-rendu avec sections : participants, décisions, actions (avec responsable et délai si mentionné).', 'Toutes les décisions et actions mentionnées dans la transcription sont reprises, rien d''inventé.', 'Transversal');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (13, 'Productivité Personnelle', 'Consultant Interne / Analyste de Direction', 'Veille concurrentielle et synthèse de rapport', 'Voici un extrait de rapport d''activité d''un opérateur concurrent : [texte du rapport]. Extrais les 3 KPIs financiers clés et les tendances de marché mentionnées.', 'Liste des KPIs avec leurs valeurs, et un résumé des tendances en 3-4 phrases.', 'KPIs extraits fidèlement au texte source, pas de chiffres inventés.', 'Transversal');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (14, 'Productivité Personnelle', 'Consultant Interne / Analyste de Direction', 'Gestion de boîte mail saturée', 'Voici une liste de 5 emails reçus : [textes des emails]. Classe-les par priorité (urgent/normal/faible) et propose une réponse courte pour l''email le plus urgent.', 'Classement des 5 emails avec justification courte, + brouillon de réponse pour le plus urgent.', 'Classement cohérent avec le contenu réel des emails, réponse proposée pertinente et professionnelle.', 'Transversal');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (15, 'Conseiller Service Client', 'Conseiller Service Client (Call Center)', 'Chatbot service client (RAG)', 'Un client demande : ''Comment activer mon forfait 4G+ depuis l''application My Ooredoo ?'' Réponds en te basant sur la FAQ fournie en contexte.', 'Réponse étape par étape basée sur la FAQ, ton clair et orienté self-service.', 'Réponse fidèle à la FAQ source, pas d''étapes inventées non présentes dans le document.', 'Metier');
INSERT INTO scenarios (id, departement, metier, nom_cas_usage, prompt, sortie_attendue, critere_succes, type_categorie) VALUES (16, 'Conseiller Service Client', 'Conseiller Service Client (Call Center)', 'Analyse de sentiment sur appel client', 'Voici la transcription d''un appel client : [texte transcript]. Détermine le sentiment global (positif/neutre/négatif) et identifie le principal point d''irritation mentionné, s''il y en a un.', 'Sentiment classé + point d''irritation identifié avec citation courte du transcript à l''appui.', 'Classification cohérente avec le ton du transcript, point d''irritation réellement présent dans le texte.', 'Metier');

-- Table: documents_vectorises
DROP TABLE IF EXISTS documents_vectorises CASCADE;
CREATE TABLE documents_vectorises (
id INTEGER NOT NULL DEFAULT nextval('documents_vectorises_id_seq'::regclass),
departement VARCHAR NOT NULL,
contenu TEXT NOT NULL,
embedding NULL NULL,
  PRIMARY KEY (id)
);

